const FA_DIGITS = '۰۱۲۳۴۵۶۷۸۹';
const fa = s => String(s == null ? '' : s).replace(/\d/g, d => FA_DIGITS[d]);
const en = s => String(s == null ? '' : s).replace(/[۰-۹]/g, d => FA_DIGITS.indexOf(d)).replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d));
const uid = () => Math.random().toString(36).slice(2, 8) + Date.now().toString(36).slice(-4);
const clone = o => JSON.parse(JSON.stringify(o));
const clamp = (n, a, b) => Math.max(a, Math.min(b, n));
const chunk = (arr, n) => { const out = []; for (let i = 0; i < arr.length; i += n) out.push(arr.slice(i, i + n)); return out; };
const range = (a, b) => { const o = []; for (let i = a; i <= b; i++) o.push(i); return o; };
const plural = (n, w) => `${fa(n)} ${w}`;
const isObj = v => v && typeof v === 'object' && !Array.isArray(v);
function deepMerge(target, patch) {
  for (const k of Object.keys(patch)) {
    if (['__proto__','constructor','prototype'].includes(k)) continue;
    const v = patch[k];
    if (isObj(v) && isObj(target[k])) deepMerge(target[k], v);
    else target[k] = isObj(v) ? deepMerge({}, v) : v;
  }
  return target;
}
function debounce(fn, ms) { let t; return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); }; }
function normalizeName(s) {
  return String(s || '').replace(/[يى]/g, 'ی').replace(/ك/g, 'ک').replace(/\u200c+$/g, '').replace(/^\u200c+/g, '').replace(/\s+/g, ' ').trim();
}
function normKey(s) { return normalizeName(s).replace(/[\s\u200c]/g, ''); }
function copyText(text) {
  const done = () => ui.toast('کپی شد', { icon: 'check' });
  const fallback = () => {
    const ta = document.createElement('textarea'); ta.value = text; ta.style.cssText = 'position:fixed;opacity:0;top:0;left:0'; document.body.appendChild(ta); ta.select();
    try { document.execCommand('copy'); done(); } catch (e) { ui.toast('کپی انجام نشد'); }
    ta.remove();
  };
  if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(text).then(done, fallback); else fallback();
}
function shareText(text, title) {
  if (navigator.share) navigator.share({ title: title || 'مهریار', text }).catch(() => {}); else copyText(text);
}
function stripHtml(html) {
  const d = document.createElement('div'); d.innerHTML = html.replace(/<\/(p|div|tr|li|h\d|section)>/g, '\n').replace(/<br\s*\/?>/g, '\n').replace(/<\/t[dh]>/g, ' | ');
  return d.textContent.replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
}
function todayFa() {
  try { return new Intl.DateTimeFormat('fa-IR', { year: 'numeric', month: 'long', day: 'numeric' }).format(new Date()); } catch (e) { return ''; }
}
function currentYearLabel() {
  try {
    const y = parseInt(en(new Intl.DateTimeFormat('fa-IR', { year: 'numeric' }).format(new Date())), 10);
    const m = parseInt(en(new Intl.DateTimeFormat('fa-IR', { month: 'numeric' }).format(new Date())), 10);
    const start = m >= 6 ? y : y - 1;
    return fa(start) + '–' + fa(start + 1);
  } catch (e) { return '۱۴۰۴–۱۴۰۵'; }
}
/* رجیستری هندلرها برای رشته‌های HTML */
const H = new Map(); let hid = 0;
function h(fn) { const id = 'h' + (++hid); H.set(id, fn); return id; }
document.addEventListener('click', e => {
  const el = e.target.closest('[data-click]'); if (!el) return;
  const fn = H.get(el.dataset.click); if (fn) fn(e, el);
});
document.addEventListener('input', e => {
  const el = e.target.closest('[data-input]'); if (!el) return;
  const fn = H.get(el.dataset.input); if (fn) fn(el.value, el, e);
});
document.addEventListener('change', e => {
  const el = e.target.closest('[data-change]'); if (!el) return;
  const fn = H.get(el.dataset.change); if (fn) fn(el.value, el, e);
});
document.addEventListener('keydown', e => {
  if(e.isComposing||e.keyCode===229)return;
  const el = e.target.closest('[data-key]'); if (!el) return;
  const fn = H.get(el.dataset.key); if (fn) fn(e, el);
});
document.addEventListener('focusout', e => {
  const el = e.target.closest && e.target.closest('[data-blur]'); if (!el) return;
  const fn = H.get(el.dataset.blur); if (fn) fn(el, e);
});

