  const dl = DEFAULT_LISTS();
  for (const k of Object.keys(dl)) if (!Array.isArray(s.lists[k]) && !isObj(s.lists[k])) s.lists[k] = dl[k];
  if (!isObj(s.lists.assessCriteria)) s.lists.assessCriteria = dl.assessCriteria;
