/* ============================================================
   JS — Router
   ============================================================ */
const ROUTES = [
  [/^#\/welcome$/, () => renderWelcome()],
  [/^#\/home$/, () => renderHome()],
  [/^#\/class$/, () => renderClass()],
  [/^#\/students$/, () => renderStudents()],
  [/^#\/students\/import$/, () => renderImport()],
  [/^#\/students\/done$/, () => renderStudentsDone()],
  [/^#\/students\/([a-zA-Z0-9_-]+)$/, m => renderStudent(m[1])],
  [/^#\/settings$/, () => renderSettings()],
  [/^#\/settings\/fields$/, () => renderFields()],
  [/^#\/settings\/meeting$/, () => renderMeetingSettings()],
  [/^#\/settings\/messages$/, () => renderMessagesList()],
  [/^#\/settings\/messages\/([a-zA-Z0-9_-]+)$/, m => renderMessageEdit(m[1])],
  [/^#\/settings\/data$/, () => renderData()],
  [/^#\/settings\/appearance$/, () => renderAppearance()],
  [/^#\/settings\/help$/, () => renderHelp()],
  [/^#\/settings\/list\/([a-zA-Z0-9_.-]+)$/, m => renderSettingsList(m[1])],
  [/^#\/outputs$/, () => renderOutputs()],
  [/^#\/output\/([a-zA-Z0-9_-]+)$/, m => renderOutput(m[1])],
];
let currentHash = '';
let currentFn = null;
function route() {
  const h = location.hash || '#/home';
  for (const [re, fn] of ROUTES) {
    const m = h.match(re);
    if (m) {
      if (h !== currentHash) { H.clear(); closeAllLayers(); currentHash = h; const app = $('#app'); if (app) app.scrollTop = 0; }
      currentFn = () => fn(m);
      fn(m); saveLastRoute(h); return;
    }
  }
  location.hash = '#/home';
}
window.addEventListener('hashchange', route);
function saveLastRoute(h) { if (h === '#/welcome') return; state.ui.lastRoute = h; dirty = true; persist(); }
let renderQueued = false;
function scheduleRender() {
  if (renderQueued) return; renderQueued = true;
  requestAnimationFrame(() => { renderQueued = false; rerender(); });
}
function rerender() {
  if (!currentFn) return;
  const app = $('#app'); const top = app ? app.scrollTop : 0;
  const active = document.activeElement; const activeId = active && active.id;
  const activeSegment=active?.closest('.seg');const segmentIndex=activeSegment?[...document.querySelectorAll('.seg')].indexOf(activeSegment):-1;const segmentValue=active?.dataset?.v;
  const sel = active && typeof active.selectionStart === 'number' ? [active.selectionStart, active.selectionEnd] : null;
  keepScroll = true;
  currentFn();
  keepScroll = false;
  if (app) app.scrollTop = top;
  if (activeId) { const el = document.getElementById(activeId); if (el && el !== document.activeElement) { el.focus({ preventScroll: true }); try { if (sel) el.setSelectionRange(sel[0], sel[1]); } catch (e) {} } }
  else if(segmentIndex>=0&&segmentValue!==undefined){const group=document.querySelectorAll('.seg')[segmentIndex];const el=group&&[...group.querySelectorAll('[role=tab]')].find(el=>el.dataset.v===segmentValue);el?.focus({preventScroll:true});}
}
let keepScroll = false;
/* انتخاب دانش‌آموزان هدف (تابع مشترک) */
function getTargetStudents(state, key, override) {
  const s = override || getSettings(key);
  let list = state.students.slice();
  if (Array.isArray(s.selectedIds)) list = list.filter(st => s.selectedIds.includes(st.id));
  if (s.sortBy === 'name') list.sort((a, b) => a.name.localeCompare(b.name, 'fa'));
  return list;
}
