  const render = () => { elCounter = 1000; return `<div class="sheet"><div class="sheet-handle" aria-hidden="true"></div><div class="sheet-head">${o.left || '<span style="width:44px"></span>'}<h3>${o.title || ''}${o.subtitle ? `<div class="sub" id="sheet-sub">${subOf()}</div>` : ''}</h3>${o.right || ui.iconBtn('x', () => api.close(), { cls: 'muted', label: 'بستن' })}</div><div class="sheet-body">${typeof o.body === 'function' ? o.body() : o.body}</div>${o.footer ? `<div class="sheet-foot">${typeof o.footer === 'function' ? o.footer() : o.footer}</div>` : ''}</div>`; };
