ui.confirm = (title, o = {}) => new Promise(res => ui.actionSheet({ title, message: o.message || '', actions: [{ label: o.ok || 'تأیید', destructive: !!o.destructive, bold: true, onClick: () => res(true) }], cancel: o.cancel || 'انصراف', onCancel: () => res(false) }));
