/* پوستهٔ صفحه */
const TABS = [['#/home', 'خانه', 'home'], ['#/students', 'دانش‌آموزان', 'people'], ['#/outputs', 'ابزارها', 'tools'], ['#/settings', 'تنظیمات', 'gear']];
function activeTab() { const hh = location.hash; if (/^#\/(students|class)/.test(hh)) return '#/students'; if (/^#\/output/.test(hh)) return '#/outputs'; if (/^#\/settings/.test(hh)) return '#/settings'; return '#/home'; }
