  view.innerHTML = sidebar() + `<div class="shell"><header class="nav ${o.large ? '' : 'plain'}"><div class="nav-side">${backHtml}</div><div class="nav-title">${o.title || ''}</div><div class="nav-side end">${o.actions || ''}${o.help ? ui.helpButton(o.help) : ''}</div></header><main class="content ${o.bottom ? 'has-bottom' : ''}" id="content">${o.large ? `<h1 class="large-title">${o.title}${o.titleExtra ? `<span class="sub">${o.titleExtra}</span>` : ''}</h1>` : ''}${o.content}</main>${o.bottom ? `<div class="bottom-bar"><div class="bottom-bar-in">${o.bottom}</div></div>` : ''}</div>` + tabbar();
