  const addRow = `<div class="el-add">${ui.tile('plus', 'green', 32)}<input id="${listId}-add" placeholder="${esc(o.placeholder || '+ افزودن مورد')}" aria-label="افزودن مورد" data-key="${h((e, el) => { if (e.key === 'Enter') { const t = normalizeName(el.value); if (!t) return; el.value = ''; pendingFocus = listId + '-add'; commit(items.concat([create(t)])); } })}" data-blur="${h(el => { const t = normalizeName(el.value); if (!t) return; el.value = ''; commit(items.concat([create(t)])); })}"></div>`;
  const foot = `<div class="el-foot"><span class="sub">${plural(items.length, 'مورد')} · برای ویرایش روی متن بزنید</span>${o.defaults ? ui.btnPlain('بازگشت به پیش‌فرض', async () => { if (await ui.confirm('بازگشت به پیش‌فرض؟', { message: 'تغییرات شما در این لیست حذف می‌شود.', ok: 'بازگردان' })) commit(clone(typeof o.defaults === 'function' ? o.defaults() : o.defaults), 'به پیش‌فرض بازگشت', items); }, { sm: true }) : ''}</div>`;
