/* ⑨ پیام‌ساز اولیا */
const msgPick = {};
function buildMessage(m, s, st, extra) {
  const vars = Object.assign({ 'مهلت': s.deadline || 'فردا' }, extra || {});
  if (st) { vars['نام'] = st.name; vars['موارد'] = numbered(missingItems(st)) || '—'; }
  let text = fillTemplate(m.template, vars);
  if (s.signature) text += '\n' + s.signature;
  return text;
}
