    if (f.fa) levelTable('فارسی'); if (f.math) levelTable('ریاضی');
    const checklist = (title, crit) => chunk(targets, 30).forEach(g => pages.push(P.page(P.head(s, `چک‌لیست ${title}`) + `<table class="att-table"><colgroup><col style="width:8mm"><col style="width:42mm">${crit.map(() => '<col>').join('')}</colgroup><thead><tr><th>ردیف</th><th>نام</th>${crit.map(c => `<th class="small-th">${esc(c)}</th>`).join('')}</tr></thead><tbody>${g.map(st => `<tr><td>${fa(st.no)}</td><td class="name-cell">${esc(st.name)}</td>${crit.map(() => '<td></td>').join('')}</tr>`).join('')}</tbody></table><div class="legend">✓ دارد &nbsp; ○ تا حدی &nbsp; ✗ ندارد</div>`, s)));
    if (f.reading) checklist('روخوانی', getList('assessCriteria.reading')); if (f.dictation) checklist('املا', getList('assessCriteria.dictation')); if (f.attention) checklist('دقت و توجه', getList('assessCriteria.attention'));
