const homeBeforeCalm=renderHome;
renderHome=function(){homeBeforeCalm();const root=$('#content');const existing=[...root.children];const more=document.createElement('details');more.className='calm-details';const summary=document.createElement('summary');summary.textContent='جزئیات آماده‌سازی و ابزارهای قبلی';more.append(summary);const detailBody=document.createElement('div');detailBody.className='details-body';more.append(detailBody);for(const el of existing){if(el.matches('h1,.hero,section.pulse'))continue;detailBody.append(el);}const n=activeStudents().length;const due=dueFollowups().length;root.classList.add('calm-home');root.innerHTML=`<div class="hero">${heroBg()}<div class="hero-body"><h2>مهریار، کنار کلاس شما</h2><p>از آماده‌سازی اول مهر تا یادگیری هر دانش‌آموز</p><div class="hero-count">${n?fa(n)+' دانش‌آموز · '+esc(className()||'کلاس شما'):'از ساختن کلاس خودت شروع کن'}</div></div></div><h1 class="calm-section-title">الان چه کاری داری؟</h1><a class="calm-choice" href="#/outputs">${ui.tile('print','green',52)}<span class="grow"><b>کلاسم را آماده کنم</b><small>برگه‌ها، وسایل و کارهای اول مهر</small></span>${icon('chevron','chev')}</a><a class="calm-choice" href="#/pulse">${ui.tile('chart','teal',52)}<span class="grow"><b>به یادگیری بچه‌ها رسیدگی کنم</b><small>ثبت مشاهده، قدم بعدی و پیگیری نتیجه</small></span>${icon('chevron','chev')}</a>${!n?`<div class="mt16">${link('#/students/import','ابتدا اسامی کلاس را وارد کنم','people')}</div>`:''}${due?`<a class="calm-followup" href="#/pulse/followups">${icon('bell')}<span>${fa(due)} پیگیری موعددار برای بررسی داری</span>${icon('chevron','chev')}</a>`:''}`;root.append(more);pruneHandlers();};
renderPulse=function(){const due=dueFollowups().length;pulseMount('نبض‌کلاس',`<div class="pulse-hub"><div class="hero">${heroBg()}<div class="hero-body"><h2>قدم بعدی برای بچه‌ها چیست؟</h2><p>یک مشاهدهٔ کوتاه، یک اقدام مشخص.</p></div></div><div class="shortcut-grid">${[['quick','ثبت سریع','یادگیری امروز را ثبت کنم','pencil','green'],['radar','توجه امروز','ببینم چه کسی به توجه نیاز دارد','eye','teal'],['tomorrow','برنامهٔ فردا','برای گروه‌ها کار مشخص بچینم','calendar','blue'],['followups','گزارش و پیگیری','اقدام قبلی را تا نتیجه دنبال کنم','check','indigo']].map(([r,t,sub,ic,g])=>`<a class="shortcut" href="#/pulse/${r}">${ui.tile(ic,g,40)}<div><b>${t}</b><p class="sub">${sub}</p></div></a>`).join('')}</div>${due?`<a class="calm-followup" href="#/pulse/followups">${icon('bell')}<span>${fa(due)} پیگیری موعددار منتظر بررسی است</span>${icon('chevron','chev')}</a>`:''}${!activeStudents().length?note('برای شروع، اسامی کلاس را وارد کن؛ یا نمونهٔ آزمایشی را امتحان کن.')+`<div class="pulse-actions">${link('#/students/import','ورود اسامی','people')}${ui.btnTinted('دیدن نمونه',loadSample)}</div>`:''}<details class="calm-details"><summary>سابقه، گروه‌ها و گزارش هفته</summary><div class="details-body">${ui.list([['sessions','جلسه‌های ثبت‌شده','notebook'],['paths','سه مسیر یادگیری','group'],['week','گزارش هفته','chart']].map(([r,t,ic])=>ui.row({title:t,icon:ic,gradient:'blue',href:'#/pulse/'+r})).join(''))}</div></details><details class="calm-details"><summary>کمک‌های کلاس</summary><div class="details-body">${ui.list(EXTRA_LINKS.map(([r,t,ic])=>ui.row({title:t,icon:ic,gradient:'teal',href:'#/pulse/'+r})).join(''))}</div></details></div>`);};
// Router entries created earlier held the original function reference.
for(const entry of ROUTES){if(entry[0].test('#/pulse'))entry[1]=()=>renderPulse();}


/* Storage controller, revision 4.
   A session can work in memory even when the host blocks localStorage.
   Disk writes, in-memory acceptance and recovery are separate outcomes.
   A previous unreadable value is never overwritten by an automatic write. */
const storageRuntime={mode:'persistent',reason:'',raw:null,lastWrite:'none',migrationPending:false,writeNoticeShown:false,realDirty:false};
function markStorageMode(mode,reason=''){
  storageRuntime.mode=mode;storageRuntime.reason=reason;
  storageOk=mode==='persistent';savingBlocked=mode==='recovery';loadWarning='';
}
function classifyStorageError(e){return /quota/i.test((e?.name||'')+' '+(e?.message||''))?'quota':'unavailable';}
loadState=function(){
  storageRuntime.raw=null;storageRuntime.migrationPending=false;
  let raw;
  try{raw=localStorage.getItem(STORAGE_KEY);}
  catch(e){state=migrate({});markStorageMode('temporary','unavailable');return;}
  if(raw){
    storageRuntime.raw=raw;
    let saved;
    try{saved=JSON.parse(raw);validateImport(saved);state=migrate(saved);}
    catch(e){state=migrate({});markStorageMode('recovery','invalid');return;}
    // Readable class stays available even if writing the migration fails.
    storageRuntime.migrationPending=!saved.learning;
    if(storageRuntime.migrationPending){
      try{localStorage.setItem(STORAGE_KEY+'_before_learning',raw);localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageRuntime.migrationPending=false;storageRuntime.raw=JSON.stringify(state);markStorageMode('persistent');}
      catch(e){markStorageMode('temporary',classifyStorageError(e));}
    }else{
      try{const probe=STORAGE_KEY+'_probe';localStorage.setItem(probe,'1');localStorage.removeItem(probe);markStorageMode('persistent');}
      catch(e){markStorageMode('temporary',classifyStorageError(e));}
    }
  }else{
    state=migrate({});
    try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));markStorageMode('persistent');}
    catch(e){markStorageMode('temporary',classifyStorageError(e));}
  }
};
function saveToDevice(){
  if(demoMode){storageRuntime.lastWrite='demo';return false;}
  if(storageRuntime.mode==='recovery'){storageRuntime.lastWrite='protected';return false;}
  try{
    if(storageRuntime.migrationPending&&storageRuntime.raw){localStorage.setItem(STORAGE_KEY+'_before_learning',storageRuntime.raw);}
    const json=JSON.stringify(state);localStorage.setItem(STORAGE_KEY,json);
    storageRuntime.migrationPending=false;storageRuntime.raw=json;storageRuntime.lastWrite='persistent';dirty=false;markStorageMode('persistent');
    return true;
  }catch(e){storageRuntime.lastWrite='memory';markStorageMode('temporary',classifyStorageError(e));return false;}
}
flushSave=function(){
  clearTimeout(saveTimer2);ensureMeta();
  if(demoMode){storageRuntime.lastWrite='demo';return true;}
  if(storageRuntime.mode!=='persistent'){
    storageRuntime.lastWrite=storageRuntime.mode==='recovery'?'protected':'memory';
    dirty=true;queueMicrotask(renderStorageNotice);return true;
  }
  if(saveToDevice())showSaved();else queueMicrotask(renderStorageNotice);
  // True means accepted in this page, NOT proof of a persistent disk write.
  return true;
};
persist=function(){
  clearTimeout(saveTimer2);if(demoMode)return;
  if(storageRuntime.mode!=='persistent'){dirty=true;queueMicrotask(renderStorageNotice);return;}
  const epoch=saveEpoch;saveTimer2=setTimeout(()=>{if(epoch===saveEpoch&&!demoMode)flushSave();},400);
};
const deviceSavedIndicator=showSaved;
showSaved=function(){if(!demoMode&&storageRuntime.lastWrite==='persistent'&&storageRuntime.mode==='persistent')deviceSavedIndicator();};
function renderStorageNotice(){
  document.getElementById('storage-alert')?.remove();
  const content=document.getElementById('content');if(!content)return;
  let el=document.getElementById('storage-notice');
  if(storageRuntime.mode==='persistent'||demoMode){el?.remove();return;}
  const recovery=storageRuntime.mode==='recovery';
  const title=recovery?'دادهٔ قبلی نیاز به بازیابی دارد':'ذخیرهٔ موقت در این صفحه';
  const sub=recovery?'نوشتن روی دادهٔ قبلی متوقف شده است.':'با بستن صفحه، تغییرات ممکن است پاک شوند.';
  if(el&&el.dataset.mode===storageRuntime.mode&&content.contains(el))return;
  el?.remove();el=document.createElement('section');el.id='storage-notice';el.className='storage-notice';el.dataset.mode=storageRuntime.mode;el.setAttribute('role','note');
  const svg=document.createElement('span');svg.className='storage-notice-icon';svg.innerHTML=icon(recovery?'lock':'info');
  const text=document.createElement('div');text.className='storage-notice-copy';const strong=document.createElement('strong');strong.textContent=title;const small=document.createElement('span');small.textContent=sub;text.append(strong,small);
  const action=document.createElement('button');action.type='button';action.textContent=recovery?'بازیابی':'راهنما';action.className='storage-notice-action';action.addEventListener('click',openStorageHelp);
  el.append(svg,text,action);content.prepend(el);
}
showStorageAlert=renderStorageNotice;
function backupFilename(){return 'مهریار-'+(className()||'کلاس')+'-'+localISO()+'.json';}
function downloadJSONText(text,filename){
  const blob=new Blob([text],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');
  a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);
}
function openBackupText(){const text=JSON.stringify(state,null,2);ui.sheet({title:'پشتیبان متنی؛ خصوصی',body:()=>`<p class="backup-help">اگر پیش‌نمایش دانلود را مسدود کرده است، این متن را کامل کپی کنید و در یک فایل با پسوند json نگه دارید. متن حاوی اطلاعات کلاس است؛ در گروه نفرستید.</p>${ui.textarea({id:'safe-backup-text',value:text,style:'min-height:210px',cls:'mono'})}`,footer:()=>ui.btnTinted('انتخاب تمام متن',()=>{const el=$('#safe-backup-text');el.focus();el.select();},{block:true})});}
exportJSON=function(){
  ensureMeta();const text=JSON.stringify(state,null,2);
  try{downloadJSONText(text,backupFilename());ui.toast('درخواست دانلود پشتیبان ارسال شد؛ پوشهٔ دانلودها را بررسی کنید.');}
  catch(e){openBackupText();}
};
function downloadRawRecovery(){
  if(!storageRuntime.raw){try{storageRuntime.raw=localStorage.getItem(STORAGE_KEY);}catch(e){}}
  if(!storageRuntime.raw){ui.toast('نسخهٔ قبلی در این محیط قابل خواندن نیست.');return;}
  try{downloadJSONText(storageRuntime.raw,'mehryar-previous-recovery.json');ui.toast('نسخهٔ قبلی برای دانلود آماده شد؛ فایل دریافتی را بررسی کنید.');}catch(e){ui.toast('دانلود در این محیط مسدود است.');}
}
async function retryDeviceStorage(){
  if(demoMode){ui.toast('برای بررسی ذخیرهٔ کلاس، ابتدا از نمونه خارج شوید.');return false;}
  if(storageRuntime.mode==='recovery'){ui.toast('ابتدا نسخهٔ قبلی را بازیابی کنید؛ روی آن نوشته نشد.');return false;}
  let current;
  try{current=localStorage.getItem(STORAGE_KEY);}catch(e){markStorageMode('temporary','unavailable');renderStorageNotice();return false;}
  // Access may have returned after an initially blocked read. Never replace a
  // newly discovered class silently with the temporary class.
  if(current&&current!==storageRuntime.raw){
    const ok=await ui.confirm('دادهٔ دیگری روی این دستگاه وجود دارد', {message:'برای جایگزینی با اطلاعات این صفحه، ابتدا نسخهٔ قبلی در حافظهٔ بازیابی نگه داشته می‌شود. اگر می‌خواهید کلاس قبلی را نگه دارید، انصراف بزنید.',ok:'پشتیبان قبلی و ذخیرهٔ این صفحه'});
    if(!ok)return false;
    try{localStorage.setItem(STORAGE_KEY+'_before_import',current);}catch(e){markStorageMode('temporary',classifyStorageError(e));return false;}
  }
  const ok=saveToDevice();renderStorageNotice();if(ok)showSaved();return ok;
}
function openStorageHelp(){
  let message='';const recovery=storageRuntime.mode==='recovery';
  const sheet=ui.sheet({title:recovery?'بازیابی امن داده':'ذخیره‌سازی در این محیط',body:()=>`<div class="storage-help"><h3>${recovery?'نسخهٔ قبلی دست‌نخورده است':'برنامه کار می‌کند، اما ذخیرهٔ دائمی فعال نیست'}</h3><p>${recovery?'دادهٔ قبلی معتبر شناخته نشد یا نسخه‌اش پشتیبانی نمی‌شود. برنامه خودکار روی آن نمی‌نویسد. ابتدا فایل بازیابی را دریافت و سپس پشتیبان معتبر را بارگذاری کنید.':'این محیط اجازهٔ ذخیره‌سازی نمی‌دهد، یا حافظه پر شده است. ثبت‌ها فقط در همین صفحه باقی می‌مانند و ممکن است با بستن آن از بین بروند.'}</p><ol><li>اگر اطلاعات وارد کرده‌اید، ابتدا پشتیبان JSON بگیرید.</li><li>فایل HTML را دانلود کنید و در صورت امکان در مرورگر اصلی، مثل Chrome یا Firefox، باز کنید؛ نه پیش‌نمایش داخل پیام‌رسان.</li><li>اگر باز هم ذخیره مسدود بود، از پشتیبان استفاده کنید. بازشدن در مرورگر اصلی هم تضمین ذخیره نیست.</li></ol><p class="storage-help-note">این برنامه نمی‌تواند محدودیت امنیتی مرورگر را دور بزند. داده‌های کلاس را برای معرفی برنامه به همکاران نفرستید.</p><div id="storage-retry-result" role="status">${esc(message)}</div></div>`,footer:()=>`<div class="storage-help-buttons">${ui.btnPrimary('پشتیبان JSON',exportJSON,{icon:'download'})}${ui.btnGray('اگر دانلود نشد: متن پشتیبان',openBackupText)}${recovery?ui.btnTinted('دریافت دادهٔ قبلی',downloadRawRecovery):ui.btnTinted('بررسی دوبارهٔ ذخیره',async()=>{const ok=await retryDeviceStorage();message=ok?'ذخیره روی دستگاه انجام شد.':'ذخیره هنوز فعال نیست؛ اطلاعات فعلاً در همین صفحه است.';if(sheet.el.isConnected){const r=$('#storage-retry-result',sheet.el);if(r)r.textContent=message;}})}</div>`});
}
replaceState=function(data){
  let next;try{validateImport(data);next=migrate(data);}catch(e){ui.toast('فایل معتبر نیست؛ دادهٔ فعلی تغییر نکرد.');return false;}
  clearTimeout(saveTimer2);saveEpoch++;
  if(demoMode){state=next;dirty=false;applyTheme();scheduleRender();return true;}
  let persisted=false;
  if(storageRuntime.mode==='persistent'){
    try{const previous=localStorage.getItem(STORAGE_KEY);if(previous)localStorage.setItem(STORAGE_KEY+'_before_import',previous);localStorage.setItem(STORAGE_KEY,JSON.stringify(next));storageRuntime.raw=JSON.stringify(next);persisted=true;}
    catch(e){markStorageMode('temporary',classifyStorageError(e));}
  }
  // In a restricted preview imports still work in memory. Recovery stays
  // protected until an explicitly authorised persistent replacement.
  state=next;dirty=!persisted;storageRuntime.lastWrite=persisted?'persistent':'memory';storageRuntime.migrationPending=false;loadWarning='';applyTheme();scheduleRender();return true;
};
const originalToastForStorage=ui.toast;
ui.toast=function(text,options={}){
  if(!demoMode&&storageRuntime.mode!=='persistent'&&/ذخیره شد|بارگذاری شد|ثبت شد/.test(text)&&!/دانلود|کپی|پشتیبان/.test(text)){
    renderStorageNotice();
    const label=document.querySelector('#storage-notice .storage-notice-copy strong');
    if(label){label.textContent='ثبت شد — فقط در همین صفحه';label.setAttribute('role','status');}
    return;
  }
  originalToastForStorage(text,options);
};
finishIntro=function(path){state.progress.pulseIntroSeen=true;state.progress.welcomeSeen=true;dirty=true;flushSave();introIndex=0;location.hash=path;};
const enterDemoBeforeStorage=loadSample;
loadSample=function(){if(!demoMode)storageRuntime.realDirty=dirty;enterDemoBeforeStorage();$('#save-ind')?.classList.remove('show');queueMicrotask(renderStorageNotice);};
const exitDemoBeforeStorage=exitDemo;
exitDemo=function(){if(!demoMode)return;exitDemoBeforeStorage();dirty=storageRuntime.realDirty;queueMicrotask(renderStorageNotice);};
const mountBeforeStorage=mount;
mount=function(options){mountBeforeStorage(options);queueMicrotask(renderStorageNotice);};
const dataBeforeStorage=renderData;
renderData=function(){dataBeforeStorage();const root=$('#content');
  // Replace the legacy second storage warning with one concise controller.
  root.querySelectorAll('.banner').forEach(el=>{if(/ذخیره‌سازی محلی در این مرورگر/.test(el.textContent))el.remove();});
  const saveButtons=[...root.querySelectorAll('button')].filter(el=>el.textContent.trim()==='ذخیرهٔ دستی');
  saveButtons.forEach(el=>{el.removeAttribute('data-click');el.addEventListener('click',async()=>{if(demoMode){ui.toast('نمونه فقط موقت است.');return;}if(storageRuntime.mode==='persistent'){flushSave();if(storageRuntime.mode!=='persistent')openStorageHelp();}else openStorageHelp();});});
  const fallback=document.createElement('div');fallback.className='backup-fallback';fallback.innerHTML=ui.btnTinted('راهنمای ذخیره و پشتیبان متنی',openStorageHelp,{block:true});root.append(fallback);queueMicrotask(renderStorageNotice);
};


