document.addEventListener('change',function(event){
  const target=event.target;
  if(!target.classList||!target.classList.contains('intro-delivery-check'))return;
  const root=target.closest('.shortage-demo-native');if(!root)return;
  const pending=Array.from(root.querySelectorAll('.intro-delivery-check')).filter(input=>!input.checked);
  const result=root.querySelector('.shortage-demo-result');
  result.replaceChildren();
  const heading=document.createElement('strong');heading.textContent='نیازمند پیگیری: '+fa(pending.length)+' مورد';result.appendChild(heading);
  const list=document.createElement('p');
  if(!pending.length)list.textContent='در این مثال، همهٔ موارد تحویل گرفته شدند.';
  pending.forEach((input,i)=>{if(i)list.appendChild(document.createElement('br'));list.appendChild(document.createTextNode(input.dataset.student+' — '+input.dataset.item));});
  result.appendChild(list);
});


/* Third illustrated introduction: isolated examples, never writes class data. */
function introNameOutputs(value){
  return withSample(()=>{
    const one=state.students[1];
    one.name=String(value).trim()||'نام دانش‌آموز';
    one.no=1;state.students=[one];
    const common={selectedIds:[one.id],extraBlank:0,fillEmpty:false,showSchool:false,showTeacher:false};
    const labelHtml=OUTPUTS.find(t=>t.key==='labels').renderPages(state,{...getSettings('labels'),...common,syncList:false,items:['دفتر ریاضی']})[0];
    const deskHtml=OUTPUTS.find(t=>t.key==='deskCards').renderPages(state,{...getSettings('deskCards'),...common,showNo:false,fold:false})[0];
    const parser=new DOMParser();
    const label=parser.parseFromString(labelHtml,'text/html').querySelector('.label');
    const desk=parser.parseFromString(deskHtml,'text/html').querySelector('.dc-face');
    return `<div class="name-output"><span class="name-output-title">برچسب دفتر</span>${label.outerHTML}</div><div class="name-output"><span class="name-output-title">کارت میز</span>${desk.outerHTML}</div>`;
  });
}
