 let copied=false;
 try{
   if(navigator.clipboard&&typeof navigator.clipboard.writeText==='function'){
     await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(new Error('Clipboard response timeout')),1800);try{Promise.resolve(navigator.clipboard.writeText(invitationText)).then(()=>{clearTimeout(timer);resolve();},error=>{clearTimeout(timer);reject(error);});}catch(error){clearTimeout(timer);reject(error);}});copied=true;
   }
 }catch(e){}
 if(!copied)copied=invitationLegacyCopy(root);
 button.disabled=false;
