const persianDatePartsFormatter=new Intl.DateTimeFormat('en-US-u-ca-persian',{year:'numeric',month:'2-digit',day:'2-digit',timeZone:'UTC'});
function persianPartsFromDay(day){
 const parts=persianDatePartsFormatter.formatToParts(new Date(day*86400000));
 const get=type=>Number(parts.find(p=>p.type===type).value);
 return {year:get('year'),month:get('month'),day:get('day')};
}
function persianDigitsToLatin(value){return String(value??'').replace(/[۰-۹]/g,ch=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(ch))).replace(/[٠-٩]/g,ch=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(ch))).replace(/[\u200e\u200f\u202a-\u202e\u2066-\u2069]/g,'').trim();}
function formatPersianDate(iso){
 if(!validDay(iso))return '';
 const [y,m,d]=iso.split('-').map(Number),p=persianPartsFromDay(Math.floor(Date.UTC(y,m-1,d)/86400000));
 return fa(String(p.year)+'/'+String(p.month).padStart(2,'0')+'/'+String(p.day).padStart(2,'0'));
}
function parsePersianDate(value){
 let v=persianDigitsToLatin(value);if(!v)return {kind:'empty',iso:''};
 if(/^\d{8}$/.test(v))v=v.slice(0,4)+'/'+v.slice(4,6)+'/'+v.slice(6);
 const match=/^(\d{4})\s*[\/\.\-]\s*(\d{1,2})\s*[\/\.\-]\s*(\d{1,2})$/.exec(v);
 if(!match)return {kind:'invalid',iso:''};
 const [jy,jm,jd]=match.slice(1).map(Number);
 if(jy<1000||jy>1600||jm<1||jm>12||jd<1||jd>(jm<=6?31:30))return {kind:'invalid',iso:''};
 const target=jy*10000+jm*100+jd;
 let lo=Math.floor(Date.UTC(jy+621,0,1)/86400000),hi=Math.floor(Date.UTC(jy+622,5,1)/86400000);
 while(lo<=hi){
  const middle=Math.floor((lo+hi)/2),p=persianPartsFromDay(middle),key=p.year*10000+p.month*100+p.day;
  if(key===target)return {kind:'valid',iso:new Date(middle*86400000).toISOString().slice(0,10)};
  if(key<target)lo=middle+1;else hi=middle-1;
 }
 return {kind:'invalid',iso:''};
}
function validatePersianDateInput(el,report=false){
 const parsed=parsePersianDate(el.value),ok=parsed.kind==='valid'||(parsed.kind==='empty'&&el.dataset.dateOptional==='1');
 const message=ok?'':parsed.kind==='empty'?'تاریخ شمسی را وارد کن.':'تاریخ شمسی معتبر نیست؛ مثل ۱۴۰۵/۰۶/۱۶ بنویس.';
 el.setCustomValidity(message);el.setAttribute('aria-invalid',String(!ok));
 const error=el.closest('.persian-date-field')?.querySelector('.persian-date-error');if(error){error.textContent=report?message:'';error.hidden=!report||ok;}
 return {...parsed,ok};
}
function readPersianDateInput(el){if(!el)return '';const parsed=validatePersianDateInput(el,true);return parsed.ok?parsed.iso:'';}
function validateVisiblePersianDates(){
 for(const el of document.querySelectorAll('[data-persian-date]')){
  if(!el.getClientRects().length)continue;
  if(!validatePersianDateInput(el,true).ok){el.focus({preventScroll:true});el.scrollIntoView({block:'center'});return false;}
 }
 return true;
}
const inputBeforePersianDates=ui.input;
let persianDateInputCounter=0;
ui.input=function(options){
 if(options.type!=='date')return inputBeforePersianDates(options);
 const id=options.id||'persian-date-'+(++persianDateInputCounter),hintId=id+'-format',errorId=id+'-error';
 const onInput=(value,el,event)=>{const parsed=validatePersianDateInput(el,false);if(parsed.ok&&options.onInput)options.onInput(parsed.iso,el,event);};
 const onChange=(value,el,event)=>{const parsed=validatePersianDateInput(el,true);if(!parsed.ok)return;if(parsed.kind==='valid')el.value=formatPersianDate(parsed.iso);if(options.onChange)options.onChange(parsed.iso,el,event);};
 const attrs=(options.attrs||'')+` data-persian-date data-date-optional="${options.allowEmpty?'1':'0'}" aria-describedby="${hintId} ${errorId}" autocomplete="off" dir="ltr"`;
 return `<div class="persian-date-field"><div class="persian-date-entry">${inputBeforePersianDates({...options,id,type:'text',value:formatPersianDate(options.value),inputmode:'numeric',placeholder:'۱۴۰۵/۰۶/۱۶',onInput,onChange,attrs})}<button type="button" class="persian-date-today" data-persian-today aria-label="گذاشتن تاریخ امروز">امروز</button></div><small id="${hintId}" class="persian-date-hint">شمسی · سال/ماه/روز؛ ۸ رقمِ بدون فاصله هم پذیرفته می‌شود.</small><span class="persian-date-error" id="${errorId}" role="status" hidden></span></div>`;
};
document.addEventListener('click',function(event){
 const today=event.target.closest('[data-persian-today]');if(!today)return;
 const input=today.closest('.persian-date-field').querySelector('[data-persian-date]');
 input.value=formatPersianDate(localISO());input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}));
});
