/* ===== Optional remote panel: banners, popup, anonymous counters. Empty PANEL_URL = fully off. ===== */
const APP_VERSION='4.1',PANEL_URL='https://billowing-feather-ba20.ssioojiu63.workers.dev/panel';
(()=>{
 if(!PANEL_URL)return;
 const OFF='mehryar_stats_off',DID='mehryar_did',base=(()=>{try{return new URL(PANEL_URL,location.href).href.replace(/\/+$/,'');}catch(_){return PANEL_URL.replace(/\/+$/,'');}})(),viewed=new Set();
 const ls=(k,v)=>{try{if(v===undefined)return localStorage.getItem(k);v===null?localStorage.removeItem(k):localStorage.setItem(k,v);}catch(_){}return null;};
 let id=ls(DID);if(!id){id=Array.from(crypto.getRandomValues(new Uint8Array(12)),b=>b.toString(16).padStart(2,'0')).join('');ls(DID,id);}
 const Q='mehryar_q',qget=()=>{try{return JSON.parse(ls(Q)||'{}')||{};}catch(_){return {};}};let sending=false;const setPS=s=>ls('mehryar_ps',JSON.stringify({s,t:Date.now()}));
 const flush=()=>{if(sending||!navigator.onLine)return;const q=qget();if(!Object.keys(q).length)return;sending=true;fetch(base+'/api.php?a=p',{method:'POST',body:JSON.stringify({id,v:APP_VERSION,ev:q}),keepalive:true,headers:{'Content-Type':'text/plain'}}).then(r=>r.text()).then(t=>{if(t==='1'){const cur=qget();for(const k in q){cur[k]=(cur[k]||0)-q[k];if(cur[k]<=0)delete cur[k];}ls(Q,JSON.stringify(cur));setPS('ok');}else setPS(t.trim().startsWith('<')?'blocked':'server');}).catch(()=>{setPS('network');}).finally(()=>{sending=false;});};
 const beacon=e=>{if(ls(OFF)==='1')return;const q=qget();q[e]=Math.min((q[e]||0)+1,500);ls(Q,JSON.stringify(q));flush();};
 window.__mehryarStat=beacon;window.__mehryarPanel={base,id};window.addEventListener('online',flush);
 const okHref=u=>/^https:\/\//i.test(u||''),okImg=u=>{try{return new URL(u).origin===new URL(base).origin;}catch(_){return false;}};
 let cfg=null,t0=0;
 const load=async()=>{if(cfg&&Date.now()-t0<6e5)return cfg;if(!navigator.onLine)return null;try{const c=new AbortController();const to=setTimeout(()=>c.abort(),4000);const r=await fetch(base+'/api.php?a=cfg',{signal:c.signal,cache:'no-store'});clearTimeout(to);cfg=await r.json();t0=Date.now();}catch(_){}return cfg;};
 const slots={top:'#dashboard-mahdavi-banner',bottom:'#dashboard-gift-banner'};
 const popup=p=>{
  if(!p||!p.title||document.getElementById('mehryar-popup')||!location.hash.startsWith('#/home'))return;
  const k='mehryar_popup_'+p.id;if(p.once&&ls(k))return;
  const o=document.createElement('div');o.id='mehryar-popup';o.setAttribute('role','dialog');o.setAttribute('aria-modal','true');o.style.cssText='position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,.45);display:flex;align-items:center;justify-content:center;padding:20px';
  const m=document.createElement('div');m.style.cssText='background:#fff;color:#111;max-width:380px;width:100%;border-radius:16px;padding:20px;direction:rtl;text-align:right;box-shadow:0 10px 40px rgba(0,0,0,.3)';
  const h=document.createElement('h3');h.textContent=p.title;h.style.margin='0 0 8px';
  const t=document.createElement('p');t.textContent=p.text||'';t.style.cssText='margin:0 0 16px;line-height:1.9;white-space:pre-wrap';
  const row=document.createElement('div');row.style.cssText='display:flex;gap:8px';
  const x=document.createElement('button');x.type='button';x.textContent='بستن';x.style.cssText='padding:10px 16px;border-radius:10px;border:1px solid #ccc;background:#f3f3f3;font:inherit;cursor:pointer';
  const done=()=>{if(p.once)ls(k,'1');o.remove();};x.onclick=done;o.addEventListener('click',e=>{if(e.target===o)done();});
  if(okHref(p.href)){const a=document.createElement('a');a.href=p.href;a.target='_blank';a.rel='noopener noreferrer';a.textContent=p.btn||'مشاهده';a.style.cssText='padding:10px 16px;border-radius:10px;background:#16a34a;color:#fff;text-decoration:none';a.onclick=()=>{beacon('popup_click');done();};row.append(a);}
  row.append(x);m.append(h,t,row);o.append(m);document.body.append(o);beacon('popup_view');};
 const apply=async()=>{
  const c=await load();if(!c)return;
  for(const [slot,sel] of Object.entries(slots)){
   const b=c.banners&&c.banners[slot],a=document.querySelector(sel+' a'),img=a&&a.querySelector('img');
   if(!b||!img||a.dataset.remote||!okHref(b.href)||!okImg(b.img))continue;
   const probe=new Image();probe.onload=()=>{if(!a.isConnected)return;img.src=b.img;a.href=b.href;a.dataset.remote='1';a.querySelector('.dashboard-gift-footer')?.remove();if(!viewed.has(slot)){viewed.add(slot);beacon(slot+'_view');}a.addEventListener('click',()=>beacon(slot+'_click'));};probe.src=b.img;}
  popup(c.popup);};
 const prev=renderHome;renderHome=function(){prev.apply(this,arguments);apply();};
 const day=new Date().toISOString().slice(0,10);if(ls('mehryar_open_day')!==day){ls('mehryar_open_day',day);beacon('open');}flush();
 if(typeof renderSettings==='function'){const ps=renderSettings;renderSettings=function(){ps.apply(this,arguments);const r=document.getElementById('content');if(!r||r.querySelector('#mehryar-stats-toggle'))return;const w=document.createElement('label');w.id='mehryar-stats-toggle';w.style.cssText='display:flex;gap:8px;align-items:center;margin:16px 0;font-size:14px';const cb=document.createElement('input');cb.type='checkbox';cb.checked=ls(OFF)!=='1';cb.onchange=()=>ls(OFF,cb.checked?null:'1');w.append(cb,document.createTextNode('ارسال آمار ناشناس استفاده (فقط شمارنده؛ بدون اسم، گزارش، بودجه یا متن چت)'));r.append(w);
  const st=document.createElement('div');st.id='mehryar-panel-status';st.style.cssText='font-size:13px;margin:0 0 16px;line-height:1.9';
  const msg=document.createElement('span');const show=t=>{msg.textContent=t;};
  let pst={};try{pst=JSON.parse(ls('mehryar_ps')||'{}');}catch(_){}
  const nq=Object.keys(qget()).length;
  show('وضعیت آمار: '+(pst.s?({ok:'آخرین ارسال موفق بود',blocked:'هاست درخواست را بسته است (بررسی امنیتی)',network:'اتصال برقرار نشد',server:'پنل جواب نامعتبر داد'}[pst.s]||pst.s):'هنوز ارسالی نبوده')+(nq?' · '+nq+' مورد در صف':''));
  const bt=document.createElement('button');bt.type='button';bt.textContent='آزمایش اتصال به پنل';bt.style.cssText='margin-inline-start:8px;padding:6px 12px;border-radius:8px;border:1px solid #ccc;background:#f3f3f3;font:inherit;cursor:pointer';
  bt.onclick=async()=>{show('در حال آزمایش…');try{const rr=await fetch(base+'/api.php?a=diag',{cache:'no-store'});const tx=await rr.text();let j=null;try{j=JSON.parse(tx);}catch(_){}
   show(j&&j.ok?'✅ پنل وصل است (PHP '+j.php+')':j?'⚠️ پنل جواب داد ولی مشکل دارد: '+(j.err||(!j.sqlite?'SQLite فعال نیست':!j.data_writable?'پوشهٔ data قابل نوشتن نیست':'نامشخص')):tx.trim().startsWith('<')?'❌ هاست درخواست را بسته است (بررسی امنیتی یا صفحهٔ خطا)':'❌ جواب نامعتبر: '+tx.slice(0,60));}
   catch(e){const mixed=location.protocol==='https:'&&base.startsWith('http:');let reach=false;try{await fetch(base+'/api.php?a=diag',{mode:'no-cors',cache:'no-store'});reach=true;}catch(_){}show(mixed?'❌ اپ روی https باز شده ولی آدرس پنل http است؛ مرورگر آن را می‌بندد. باید پنل https داشته باشد.':reach?'❌ سایت در دسترس است ولی هاست اجازهٔ درخواست از بیرون دامنه‌اش را نمی‌دهد (بررسی امنیتی یا CORS). مشکل از هاست است.':'❌ به سایت نرسید: آدرس را بررسی کن، اینترنت را چک کن، یا اندروید درخواست http را می‌بندد (برای APK پنل باید https باشد).');}};
  st.append(msg,bt);r.append(st);};}
})();


