/* Keyboard support for segmented controls: arrows move focus; Enter/Space
   activate the real native button. Do not double-trigger a native click. */
document.addEventListener('keydown',function(e){
 if(e.defaultPrevented||e.isComposing||e.keyCode===229)return;
 const tab=e.target.closest('.seg [role=tab]');if(!tab)return;
 const group=tab.closest('.seg');const tabs=[...group.querySelectorAll('[role=tab]:not(:disabled)')];const i=tabs.indexOf(tab);let j=i;
 if(e.key==='ArrowLeft')j=(i+1)%tabs.length;
 else if(e.key==='ArrowRight')j=(i-1+tabs.length)%tabs.length;
 else if(e.key==='Home')j=0;
 else if(e.key==='End')j=tabs.length-1;
 else return;
 e.preventDefault();tabs[j]?.focus();
});
let composingField=null,renderAfterComposition=false;
document.addEventListener('compositionstart',e=>{composingField=e.target;},true);
document.addEventListener('compositionend',()=>{composingField=null;if(renderAfterComposition){renderAfterComposition=false;scheduleRender();}},true);
const rerenderBeforeComposition=rerender;
rerender=function(){if(composingField?.isConnected){renderAfterComposition=true;return;}return rerenderBeforeComposition();};


