/* نبض کلاس: grade-aware teacher dashboard. UI state is not student evidence. */
const PD_GRADES=GRADES.filter(x=>x!=='چندپایه');
let pulseDashboardView={grade:null,anchor:localISO(),subject:''};
function pdGradeName(v){v=String(v||'').replace(/^پایه[ٔ‌\s]*/,'').trim();const n='۰۱۲۳۴۵۶۷۸۹'.indexOf(v);if(n>0&&n<7)return ['','اول','دوم','سوم','چهارم','پنجم','ششم'][n];if(/^[1-6]$/.test(v))return ['','اول','دوم','سوم','چهارم','پنجم','ششم'][+v];return PD_GRADES.includes(v)?v:'';}
function pdStudentGrade(data,id){return pdGradeName(data.learning.studentMeta[id]?.grade)||pdGradeName(data.klass.grade);}
function pdGrade(){return pulseDashboardView.grade===null?pdGradeName(state.klass.grade):pulseDashboardView.grade;}
function pdRoster(data=state,f={}){const end=f.to&&f.to<localISO()?f.to:localISO();return data.students.filter(st=>{const m=data.learning.studentMeta[st.id]||{};return !m.archived&&(!f.grade||pdStudentGrade(data,st.id)===f.grade)&&(!validDay(m.enrolledOn)||m.enrolledOn<=end);});}
// Correct existing grade filters: a mixed-grade session must not leak another
// grade's observations into a report. Individual archived histories remain readable.
const directObservationsBeforeGrades=getDirectObservations;
getDirectObservations=function(data=state,f={}){return directObservationsBeforeGrades(data,f).filter(o=>!f.grade||pdStudentGrade(data,o.studentId)===f.grade);};
groupRoster=function(f=filter){return pdRoster(state,f);};
const newSessionBeforeGrade=newSession;
newSession=function(){return {...newSessionBeforeGrade(),grade:filter.grade||''};};
function pdRange(anchor=pulseDashboardView.anchor){const ws=Number(state.learning.settings.weekStart);const first=plusDays(anchor,-((dateObj(anchor).getDay()-(Number.isInteger(ws)&&ws>=0&&ws<=6?ws:6)+7)%7));return {from:first,to:plusDays(first,6)};}
function pdStats(data=state,f={}){
 const end=f.to&&f.to<localISO()?f.to:localISO();f={...f,from:validDay(f.from)?f.from:plusDays(end,-6)};const range={...f,to:end};
 const roster=pdRoster(data,range),ids=new Set(roster.map(st=>st.id));
 const sessions=selectSessions(data,range).filter(s=>s.rosterIds.some(id=>ids.has(id)));
 const obs=getDirectObservations(data,range).filter(o=>ids.has(o.studentId)&&(!validDay(data.learning.studentMeta[o.studentId]?.enrolledOn)||data.learning.studentMeta[o.studentId].enrolledOn<=o.date));
 const seen=new Set(obs.map(o=>o.studentId));const histories=new Map();
 for(const o of obs){const key=JSON.stringify([o.studentId,o.subject,o.skillId]);if(!histories.has(key))histories.set(key,[]);histories.get(key).push(o);}
 const needs=[],trends=[];for(const history of histories.values()){const last=history.at(-1),level=getFollowupLevel(history),trend=getStudentTrend(history);if(level.key!=='none')needs.push({studentId:last.studentId,subject:last.subject,skillId:last.skillId,skillLabel:last.skillLabel,level,observations:history.length});if(history.length>=2)trends.push({studentId:last.studentId,subject:last.subject,skillId:last.skillId,skillLabel:last.skillLabel,trend});}
 const followups=data.learning.followups.filter(x=>ids.has(x.studentId)&&(!f.subject||x.subject===f.subject)&&(!validDay(x.createdOn)||x.createdOn<=end));
 const due=followups.filter(x=>validDay(x.dueOn)&&x.dueOn<=end&&x.status!=='closed'&&(x.status!=='done'||x.outcome==='unchecked')).sort((a,b)=>a.dueOn.localeCompare(b.dueOn));
 const completed=followups.filter(x=>validDay(x.completedOn)&&x.completedOn>=f.from&&x.completedOn<=end);
 const days=Array.from({length:7},(_,i)=>{const date=plusDays(f.from,i);return {date,future:date>localISO(),count:obs.filter(o=>o.date===date).length,people:new Set(obs.filter(o=>o.date===date).map(o=>o.studentId)).size};});
 const subjects=[...new Set([...SUBJECTS,...sessions.map(s=>s.subject)])].filter(subject=>!f.subject||subject===f.subject).map(subject=>({subject,sessions:sessions.filter(s=>s.subject===subject).length,observed:new Set(obs.filter(o=>o.subject===subject).map(o=>o.studentId)).size,records:obs.filter(o=>o.subject===subject).length}));
 return {range,roster,sessions,obs,seen:seen.size,unseen:roster.filter(st=>!seen.has(st.id)),coverage:roster.length?Math.round(seen.size/roster.length*100):null,needs,needStudents:new Set(needs.map(x=>x.studentId)).size,trends,due,completed,days,subjects};
}
buildWeeklySummary=function(f={from:plusDays(localISO(),-6),to:localISO()}){const d=pdStats(state,f),errors=new Map();for(const o of d.obs)for(const label of o.errors||[]){if(!errors.has(label))errors.set(label,{ids:new Set(),observations:0});errors.get(label).ids.add(o.studentId);errors.get(label).observations++;}return {sessions:d.sessions.length,days:new Set(d.sessions.map(s=>s.date)).size,seen:d.seen,unseen:d.unseen,subjects:d.subjects,errors:[...errors].map(([name,x])=>({name,students:x.ids.size,observations:x.observations}))};};
function pdFilter(){return {...pdRange(),grade:pdGrade(),...(pulseDashboardView.subject?{subject:pulseDashboardView.subject}:{})};}
function pdSync(){const r=pdRange();filter.grade=pdGrade();filter.from=r.from;filter.to=r.to<localISO()?r.to:localISO();if(pulseDashboardView.subject&&filter.subject!==pulseDashboardView.subject){filter.subject=pulseDashboardView.subject;filter.skillId=state.learning.skills.find(k=>k.subject===filter.subject)?.id||'';}}
function pdChangeGrade(v){pulseDashboardView.grade=v;pdSync();rerender();}
function pdMoveWeek(delta){const next=plusDays(pulseDashboardView.anchor,delta*7);if(pdRange(next).from>localISO())return;pulseDashboardView.anchor=next;pdSync();rerender();}
function pdControls(){const r=pdRange();return `<section class="pd-controls" aria-label="پایه و بازهٔ گزارش"><div class="pd-filter-fields">${ui.field('پایهٔ کلاس',ui.select({id:'pd-grade',value:pdGrade(),options:[['','همهٔ پایه‌ها'],...PD_GRADES],onChange:pdChangeGrade}))}${ui.field('درس در آمار',ui.select({id:'pd-subject',value:pulseDashboardView.subject,options:[['','همهٔ درس‌ها'],...SUBJECTS],onChange:v=>{pulseDashboardView.subject=v;pdSync();rerender();}}))}</div><div class="pd-week-nav">${ui.btnPlain('هفتهٔ قبل',()=>pdMoveWeek(-1),{attrs:'aria-label="هفتهٔ قبل"'})}<div><b>${r.from===pdRange(localISO()).from?'این هفته':'هفتهٔ انتخاب‌شده'}</b><small>${displayDay(r.from)} تا ${displayDay(r.to)}</small></div>${ui.btnPlain('هفتهٔ بعد',()=>pdMoveWeek(1),{disabled:plusDays(r.from,7)>localISO(),attrs:'aria-label="هفتهٔ بعد"'})}</div></section>`;}
function pdMetric(value,label,detail,tone,href){return `<a class="pd-metric ${tone}" href="${href}"><strong>${fa(value)}</strong><b>${label}</b><small>${detail}</small></a>`;}
function pdMetrics(d){return `<div class="pd-metrics">${pdMetric(d.roster.length,'دانش‌آموز','در پایهٔ انتخابی','teal','#/pulse/overview/roster')}${pdMetric(d.seen,'مشاهده‌شده','فرد یکتا در این هفته','blue','#/pulse/overview/seen')}${pdMetric(d.unseen.length,'بدون مشاهده','نیاز به فرصت دیدن، نه برچسب','slate','#/pulse/overview/unseen')}${pdMetric(d.needStudents,'نیاز تکرارشده','در همان درس و مهارت','violet','#/pulse/overview/needs')}</div>`;}
function pdChart(d){const max=Math.max(1,...d.days.map(x=>x.count)),labels=['ی','د','س','چ','پ','ج','ش'];return `<section class="pd-panel pd-chart-panel"><div class="pd-section-head"><div><h2>ریتم مشاهده‌های هفته</h2><p>تعداد ثبت‌های مستقیم؛ نه نمرهٔ کلاس</p></div><strong class="pd-total">${fa(d.obs.length)}<small>مشاهده</small></strong></div><div class="pd-bars" role="img" aria-label="${esc(d.days.map(x=>displayDay(x.date)+': '+(x.future?'روز آینده':fa(x.count)+' مشاهده')).join('؛ '))}">${d.days.map(x=>`<div class="pd-day ${x.future?'future':''}"><span>${x.future?'—':fa(x.count)}</span><div class="pd-bar-track"><i style="height:${x.count/ max*100}%"></i></div><small>${labels[dateObj(x.date).getDay()]}</small></div>`).join('')}</div>${d.obs.length?'':'<p class="pd-empty-inline">هنوز مشاهدهٔ مستقیمی در این بازه ثبت نشده است.</p>'}<div class="pd-coverage"><div><b>پوشش مشاهده</b><span>${d.coverage===null?'بدون عضو':fa(d.coverage)+'٪ · '+fa(d.seen)+' از '+fa(d.roster.length)+' نفر'}</span></div><div class="pd-meter" role="progressbar" aria-label="پوشش مشاهده" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${d.coverage||0}"><i style="width:${d.coverage||0}%"></i></div><small>فقط داشتنِ حداقل یک مشاهده را نشان می‌دهد؛ درصد یادگیری نیست.</small></div></section>`;}
function pdQuickLabel(){return quickDraft&&JSON.stringify(quickDraft)!==quickBaseline||state.learning.drafts?.new?'ادامهٔ پیش‌نویس':'ثبت مشاهدهٔ امروز';}
function pdStartQuick(){pdSync();filter.from=weekStartDay();filter.to=localISO();if(quickDraft&&JSON.stringify(quickDraft)!==quickBaseline){location.hash=quickKey&&quickKey!=='new'?'#/pulse/session/'+quickKey:'#/pulse/quick';return;}if(!state.learning.drafts?.new){quickDraft=null;quickKey='';}location.hash='#/pulse/quick';}
function pdStudentRows(students,limit=5){return students.slice(0,limit).map(st=>`<a class="pd-person" href="#/pulse/student/${st.id}"><span class="pd-person-mark">${fa(st.no||'•')}</span><span><b>${esc(st.name)}</b><small>${pdStudentGrade(state,st.id)?'پایهٔ '+esc(pdStudentGrade(state,st.id)):'پایه تعیین نشده'}</small></span>${icon('chevron')}</a>`).join('');}
function pdNext(d){let title,text,action;if(!d.roster.length){title='اول، پایه و فهرست کلاس را آماده کن';text='اگر پایهٔ انتخابی عضو ندارد، پایه را عوض کن یا دانش‌آموزان را اضافه کن.';action=link('#/students/import','واردکردن دانش‌آموزان','people');}else if(d.unseen.length){title=`برای ${fa(d.unseen.length)} نفر فرصت مشاهده بگذار`;text='یک پاسخ کوتاه و مستقل کافی است تا شروع کنی. نداشتن مشاهده، نشانهٔ ضعف نیست.';action=ui.btnPrimary(pdQuickLabel(),pdStartQuick,{icon:'pencil'});}else if(d.due.length){title=`${fa(d.due.length)} پیگیری به بازبینی نیاز دارد`;text='انجام تمرین پایان کار نیست؛ نتیجه را با مشاهدهٔ بعدی بررسی کن.';action=link('#/pulse/followups','بازکردن پیگیری‌ها','check');}else{title=d.obs.length?'قدم بعدی را برای یک مهارت انتخاب کن':'از یک مشاهدهٔ کوچک شروع کن';text='گروه‌بندی و برنامهٔ فردا را بر اساس همان مهارت بساز، نه میانگین رنگ درس‌های مختلف.';action=link('#/pulse/tomorrow','برنامهٔ فردا','calendar');}return `<section class="pd-next"><div class="pd-next-icon">${icon('sparkles')}</div><div><span class="pd-eyebrow">قدم پیشنهادی معلم</span><h2>${title}</h2><p>${text}</p>${action}</div></section>`;}
function pdGradeInfo(){const grade=pdGrade(),all=pdRoster(),unknown=all.filter(st=>!pdStudentGrade(state,st.id)),bank=grade?allActivities().filter(a=>a.grades.includes(grade)):[];return `<section class="pd-panel pd-grade-info"><div class="pd-section-head"><div><h2>${grade?'همراه پایهٔ '+esc(grade):'کلاس تو، پایه‌های تو'}</h2><p>${grade?bank.length?fa(bank.length)+' فعالیت آماده با برچسب همین پایه':'برای این پایه هنوز فعالیت آماده ثبت نشده؛ ثبت مشاهده و گزارش در دسترس است.':'برای دیدن فعالیت‌های متناسب، یک پایه انتخاب کن.'}</p></div>${icon('book')}</div><div class="pd-inline-links">${link('#/pulse/activities','فعالیت‌های پایه','book')}${link('#/pulse/grades','تنظیم پایهٔ دانش‌آموزان','people')}</div>${unknown.length?`<p class="pd-footnote">پایهٔ ${fa(unknown.length)} دانش‌آموز مشخص نیست؛ آن‌ها فقط در «همهٔ پایه‌ها» دیده می‌شوند.</p>`:''}</section>`;}
function pdToolLinks(){return `<section class="pd-panel"><div class="pd-section-head"><h2>میز کار معلم</h2><span class="pd-eyebrow">همه‌چیز در دسترس</span></div><div class="pd-tools">${[['tomorrow','برنامهٔ فردا','calendar'],['paths','گروه‌های یادگیری','people'],['radar','فرصت توجه','eye'],['sessions','جلسه‌های ثبت‌شده','docs'],['followups','پیگیری تا نتیجه','check'],['week','گزارش هفتگی','chart']].map(([route,title,ic])=>`<a href="#/pulse/${route}">${icon(ic)}<span>${title}</span></a>`).join('')}</div><details class="pd-more"><summary>کمک‌های دیگر کلاس</summary>${ui.list(EXTRA_LINKS.map(([r,t,ic])=>ui.row({title:t,icon:ic,gradient:'teal',href:'#/pulse/'+r})).join(''))}${link('#/settings/learning','تنظیمات یادگیری','gear')}</details></section>`;}
HELP.pulse={title:'داشبورد نبض‌کلاس',lines:['ابتدا پایهٔ کلاس و هفته را انتخاب کن؛ آمار فقط برای همین گروه است.','«مشاهده‌شده» یعنی حداقل یک مشاهدهٔ مستقیم؛ حضور و تکلیف جای آن را نمی‌گیرند.','نیاز تکرارشده فقط در همان درس و مهارت بررسی می‌شود: دو قرمز، سه قرمز برای پیگیری ویژه، یا دو زرد بدون قرمز.','ثبت مشاهده، گزارش هفته و برنامهٔ فردا از همین داشبورد در دسترس‌اند.','در چندپایه، پایهٔ هر دانش‌آموز را از «تنظیم پایهٔ دانش‌آموزان» تعیین کن.'],next:{label:'داشبورد نبض‌کلاس',href:'#/pulse'}};
renderPulse=function(){pdSync();const d=pdStats(state,pdFilter());mount({title:'نبض‌کلاس',back:false,help:'pulse',content:`<div class="pd-dashboard"><section class="pd-hero"><div><p>${esc(className()||'کلاس من')} · ${displayDay(localISO())}</p><h1>یک نگاه، یک قدم روشن</h1><span>ببین چه ثبت شده؛ تصمیم بگیر قدم بعدی چیست.</span></div><div class="pd-hero-symbol">${icon('chart')}</div></section>${pdControls()}<div class="pd-main-actions">${ui.btnPrimary(pdQuickLabel(),pdStartQuick,{icon:'pencil',block:true})}<a href="#/pulse/week" class="pd-week-link">${icon('chart')} گزارش هفته</a></div>${pdMetrics(d)}<div class="pd-grid"><div>${pdChart(d)}${pdNext(d)}</div><div>${pdGradeInfo()}<section class="pd-panel"><div class="pd-section-head"><h2>پیگیری‌های سررسیدشده</h2><span class="pd-count">${fa(d.due.length)}</span></div>${d.due.slice(0,3).map(f=>`<a class="pd-due-row" href="#/pulse/followups"><b>${esc(studentById(f.studentId)?.name||'دانش‌آموز')}</b><span>${esc(f.action)}</span><small>${displayDay(f.dueOn)} · ${esc(FOLLOW_STATUS[f.status]||f.status)}</small></a>`).join('')||'<p class="pd-empty-inline">پیگیری بازِ سررسیدشده‌ای در این گروه نیست.</p>'}<a class="pd-text-link" href="#/pulse/followups">همهٔ پیگیری‌های این پایه ←</a></section></div></div>${pdToolLinks()}<p class="pd-footnote">آمار این نما برای اعضای فعال فعلی و پایهٔ فعلی آن‌هاست. دادهٔ پیش‌نویس، روز آینده و سبزِ مشاهده‌نشده وارد آمار نمی‌شوند. آمار آموزشی خصوصیِ معلم است.</p>${!state.students.length?ui.btnTinted('دیدن نمونهٔ فرضی بدون تغییر اطلاعات کلاس',loadSample,{block:true}):''}</div>`});document.getElementById('content').classList.add('pd-content');};
function pdWeeklyText(d=pdStats(state,pdFilter())){const f=pdFilter(),lines=['گزارش هفتگی — خصوصی معلم',`${displayDay(f.from)} تا ${displayDay(f.to)}`,'پایه: '+(f.grade||'همهٔ پایه‌ها')+' · درس: '+(f.subject||'همهٔ درس‌��ا'),`اعضای فعال فعلی: ${d.roster.length}؛ افراد مشاهده‌شده: ${d.seen}؛ بدون مشاهده: ${d.unseen.length}`,`جلسه‌ها: ${d.sessions.length}؛ مشاهده‌های مستقیم: ${d.obs.length}؛ روزهای ثبت: ${new Set(d.sessions.map(s=>s.date)).size}`,`پوشش مشاهده: ${d.coverage===null?'بدون عضو':d.coverage+'٪'} — این عدد درصد یادگیری نیست.`,...d.subjects.map(x=>`${x.subject}: ${x.sessions} جلسه؛ ${x.observed} فرد یکتا؛ ${x.records} مشاهده`),'نیازهای تکرارشده در همان درس و مهارت:',...(d.needs.length?d.needs.map(x=>`${studentById(x.studentId)?.name||''} / ${x.subject} / ${x.skillLabel}: ${x.level.text}`):['در این بازه نیازی به آستانهٔ تکرار نرسیده است؛ این به معنی تسلط همگانی نیست.']),'روندِ دو مشاهدهٔ اخیر در یک مهارت:',...(d.trends.length?d.trends.map(x=>`${studentById(x.studentId)?.name||''} / ${x.subject} / ${x.skillLabel}: ${x.trend.text}`):['دو مشاهدهٔ مرتبط برای توصیف روند در این بازه موجود نیست.']),'بدون مشاهدهٔ مستقیم در این بازه: '+(d.unseen.map(x=>x.name).join('، ')||'هیچ‌کس در گروه انتخابی'),'اقدامات انجام‌شده در این هفته:',...(d.completed.length?d.completed.map(x=>`${studentById(x.studentId)?.name||''}: ${x.action}؛ نتیجهٔ ثبت‌شده: ${FOLLOW_OUTCOME[x.outcome]||'بررسی نشده'}`):['اقدام انجام‌شده‌ای در این بازه ثبت نشده است.']),`پیگیری سررسیدشده و باز: ${d.due.length}`,'قدم بعدی: '+(!d.obs.length?'ابتدا فرصت ثبت مشاهدهٔ مستقیم فراهم کن.':d.unseen.length?'برای افراد بدون مشاهده، یک پاسخ کوتاه و مستقل فراهم کن؛ برای نیازهای تکرارشده تمرین متناسب با پایه و سپس بازسنجی ثبت کن.':'نیازهای هر مهارت را جدا بررسی کن و نتیجهٔ اقدام را با بازسنجی ثبت کن.'),'این گزارش بر اساس اعضای فعال و پایهٔ فعلی است؛ عضویت تاریخیِ پایه بازسازی نمی‌شود. روزهای آینده و پیش‌نویس در آمار نیستند. انجام اقدام، اثبات اثر آن نیست. از رنگ درس‌های مختلف رتبهٔ کلی ساخته نمی‌شود.'];return lines.join('\n\n');}
weeklyText=function(){return pdWeeklyText();};
renderWeek=function(){pdSync();const d=pdStats(state,pdFilter()),f=pdFilter(),text=pdWeeklyText(d);mount({title:'گزارش هفتگی',backHref:'#/pulse',help:'pulse',content:`<div class="pd-dashboard pd-week-report"><section class="pd-report-title"><span>${icon('chart')}</span><div><h1>هفتهٔ کلاس، روشن و مستند</h1><p>خصوصی معلم · ${f.grade?'پایهٔ '+esc(f.grade):'همهٔ پایه‌ها'}</p></div></section>${pdControls()}${pdMetrics(d)}${pdChart(d)}<section class="pd-panel"><div class="pd-section-head"><h2>مشاهده در هر درس</h2><small>افراد یکتا؛ جمع ستون‌ها لزوماً تعداد کلاس نیست</small></div>${d.subjects.map(x=>`<div class="pd-subject-row"><b>${esc(x.subject)}</b><div class="pd-meter"><i style="width:${d.roster.length?x.observed/d.roster.length*100:0}%"></i></div><span>${fa(x.observed)} نفر</span></div>`).join('')}</section><section class="pd-panel"><h2>برای هفتهٔ بعد</h2><div class="pd-week-decisions"><a href="#/pulse/overview/unseen"><b>${fa(d.unseen.length)} نفر بدون مشاهده</b><span>فرصت پاسخ کوتاه و مستقل</span></a><a href="#/pulse/overview/needs"><b>${fa(d.needStudents)} نفر با نیاز تکرارشده</b><span>تمرین در همان مهارت، سپس بازسنجی</span></a><a href="#/pulse/followups"><b>${fa(d.completed.length)} اقدام انجام‌شده</b><span>انجام کار را با اثر آن یکی ندانیم</span></a></div></section><section class="pd-panel"><h2>متن قابل ویرایش گزارش</h2><p class="pd-footnote">ویرایش متن، داده‌های ثبت‌شده را تغییر نمی‌دهد. این گزارش حاوی نام‌ها و جزئیات خصوصی کلاس است؛ در کانال عمومی نفرست.</p>${ui.textarea({id:'pd-week-editor',value:text,style:'min-height:260px;line-height:1.9'})}<div class="pd-inline-links">${ui.btnPrimary('پیش‌نمایش و چاپ',()=>previewLearningPages('گزارش هفتگی',[learningPage('گزارش هفتگی — خصوصی معلم',read('pd-week-editor'))]),{icon:'print'})}${ui.btnTinted('کپی متن گزارش',()=>copyText(read('pd-week-editor')),{icon:'copy'})}</div></section></div>`});document.getElementById('content').classList.add('pd-content');};
function pdOverview(kind){pdSync();const d=pdStats(state,pdFilter()),names={roster:'اعضای گروه',seen:'مشاهده‌شده‌های هفته',unseen:'فرصت مشاهده برای این هفته',needs:'نیازهای تکرارشدهٔ هفته'};let students=d.roster;if(kind==='seen'){const ids=new Set(d.obs.map(o=>o.studentId));students=students.filter(s=>ids.has(s.id));}if(kind==='unseen')students=d.unseen;const content=kind==='needs'?d.needs.map(x=>`<a class="pd-person pd-need-person" href="#/pulse/student/${x.studentId}"><span><b>${esc(studentById(x.studentId)?.name||'')}</b><small>${esc(x.subject+' / '+x.skillLabel)}</small><small>${esc(x.level.text)} · ${fa(x.observations)} مشاهدهٔ مرتبط</small></span>${icon('chevron')}</a>`).join(''):pdStudentRows(students,students.length);mount({title:names[kind]||names.roster,backHref:'#/pulse',content:`<div class="pd-dashboard">${pdControls()}<section class="pd-panel"><h1 class="pd-list-title">${names[kind]||names.roster}</h1><p class="pd-footnote">${kind==='needs'?'نیاز در یک مهارت است، نه برچسب کلی دانش‌آموز.':'نداشتن مشاهده، به معنی ضعف یا غیبت نیست.'}</p>${content||'<p class="pd-empty-inline">در این گروه و بازه موردی وجود ندارد.</p>'}</section>${ui.btnPrimary(pdQuickLabel(),pdStartQuick,{block:true,icon:'pencil'})}</div>`});}
function pdGradesPage(){const rows=pdRoster(state);mount({title:'پایهٔ دانش‌آموزان',backHref:'#/pulse',content:`<section class="pd-panel"><h1 class="pd-list-title">هر دانش‌آموز، پایهٔ خودش</h1><p class="pd-footnote">این انتخاب در آمار و فهرست جلسهٔ جدید استفاده می‌شود. سابقهٔ جلسات حذف یا بازنویسی نمی‌شود. برای کلاس چندپایه، پایهٔ هر نفر را جدا انتخاب کن.</p>${rows.map(st=>`<div class="pd-grade-person"><label for="pd-grade-${st.id}">${esc(st.name)}</label>${ui.select({id:'pd-grade-'+st.id,value:state.learning.studentMeta[st.id]?.grade||'',options:[['','پایهٔ پیش‌فرض کلاس'],...PD_GRADES],onChange:v=>{ensureMeta();state.learning.studentMeta[st.id].grade=v;setState({},{silent:true});const msg=document.getElementById('pd-grade-message');if(msg)msg.textContent='پایه تغییر کرد؛ وضعیت ذخیره‌سازی برنامه را بررسی کن.';}})}</div>`).join('')||'<p>ابتدا دانش‌آموزان را وارد کن.</p>'}<p id="pd-grade-message" class="pd-footnote" role="status"></p>${link('#/class','مشخصات پایهٔ کلاس')}${link('#/pulse','بازگشت به داشبورد')}</section>`});}
const activitiesBeforeDashboard=renderActivities;
renderActivities=function(id){if(id)return activitiesBeforeDashboard(id);const grade=pdGrade(),shown=allActivities().filter(a=>(!grade||a.grades.includes(grade))&&(!pulseDashboardView.subject||a.subject===pulseDashboardView.subject)&&(!activityQ||normKey(a.title+a.skillLabel+a.subject).includes(normKey(activityQ))));mount({title:'فعالیت‌های متناسب با پایه',backHref:'#/pulse',content:`<div class="pd-dashboard">${pdControls()}<section class="pd-panel"><h1 class="pd-list-title">${grade?'فعالیت‌های پایهٔ '+esc(grade):'بانک فعالیت‌های ثبت‌شده'}</h1><p class="pd-footnote">فقط برچسب پایهٔ ثبت‌شده ملاک است؛ نبود فعالیت به معنی پیشنهاد خودکار برای پایهٔ دیگر نیست.</p>${ui.search('جست‌وجوی مهارت یا فعالیت',v=>{activityQ=v;rerender();},activityQ)}${ui.btnPrimary('افزودن فعالیت خودم',()=>editActivity(null,true))}${shown.length?ui.list(shown.map(a=>ui.row({title:esc(a.title),subtitle:esc(a.subject+' / '+a.skillLabel+' · '+a.grades.join('، ')),icon:'book',gradient:'teal',href:'#/pulse/activities/'+a.id})).join('')):'<p class="pd-empty-inline">برای این پایه و درس، فعالیتی ثبت نشده است. فعالیت متناسب خودت را اضافه کن.</p>'}</section></div>`});};
const followupsBeforeDashboard=renderFollowups;
